{
  "case_id": "xsu_sg_014_occupational_injury_opinion",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Svaret angiver begge kritiske elementer (påvirkning af evnen til at arbejde og om funktionsevnen er så nedsat, at et studiejob ikke kan have) og at udtalelsen er vejledende og ikke bindende for Udbetaling Danmark. Det stemmer med vejledningen og rubrikken. Ingen væsentlige juridiske fejl."},
    "c02_required_elements_complete": {"label": "met", "reason": "Begge kritiske elementer er med i tilsvarende formulering, og den påkrævede kvalifikation om vejledende/ikke bindende er med."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer begge dele af spørgsmålet: hvad udtalelsen skal belyse, og om Udbetaling Danmark er bundet."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde som lov, bestemmelse eller vejledningsafsnit. Efter reglen er C04 not_met."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så kildens gyldighed kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så støtten mellem påstande og kilde kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Alle udsagn kan genfindes i vejledningens afsnit 5.1.3.3. Svaret tilføjer ingen regler, betingelser eller myndigheder uden støtte."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "Den krævede kvalifikation om, at udtalelsen er vejledende og ikke bindende, er bevaret. Svaret udelader ikke forbehold, der ændrer betydningen."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er kort og sammenhængende. Konklusionen om, at udtalelsen ikke er bindende, følger af udsagnet om, at den er vejledende og indgår i den samlede vurdering."},
    "c10_legal_modality_precision": {"label": "met", "reason": "Svaret gengiver 'vejledende', 'indgår i vurderingen' og 'ikke bindende' korrekt. Det gør ikke skøn eller muligheder absolutte. 'Skal belyse' svarer til, at AES foretager en vurdering af de to forhold."}
  },
  "xhaile_coverage": {
    "A68": {"label": "partial", "reason": "Svaret dækker de to vurderingspunkter (påvirkning af arbejdsevne og om et studiejob er udelukket) og at udtalelsen er vejledende. Det nævner ikke, at Udbetaling Danmark kan anmode om udtalelsen, at den udarbejdes på foreliggende dokumentation uden undersøgelse af den uddannelsessøgende, eller at styrelsen betaler udgifterne."}
  },
  "overall_notes": "Indholdet er juridisk korrekt og dækker de kritiske elementer og den krævede kvalifikation. Svaret citerer dog ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable. Det udelader også støtteelementet om, at udtalelsen bygger på sagens dokumenter og ikke kræver undersøgelse."
}

